def findMinStep(board, hand):
    hand = ''.join(sorted(hand))

    def remove(s):
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            if j - i >= 3:
                return remove(s[:i] + s[j:])
            i = j
        return s

    memo = {}

    def dfs(b, h):
        if b == '':
            return 0
        if not h:
            return float('inf')
        if (b, h) in memo:
            return memo[(b, h)]
        res = float('inf')
        for i in range(len(h)):
            if i > 0 and h[i] == h[i - 1]:
                continue
            for j in range(len(b) + 1):
                if j > 0 and b[j - 1] == h[i]:
                    continue
                insert = False
                if j < len(b) and b[j] == h[i]:
                    insert = True
                if j > 0 and j < len(b) and b[j - 1] == b[j] and b[j - 1] != h[i]:
                    insert = True
                if not insert:
                    continue
                nb = remove(b[:j] + h[i] + b[j:])
                r = dfs(nb, h[:i] + h[i + 1:])
                if r + 1 < res:
                    res = r + 1
        memo[(b, h)] = res
        return res

    r = dfs(board, hand)
    return r if r != float('inf') else -1
